// Descriptions for the Plans page and for catalog / crafted magic items (keyed by plan id, see plans.js, or `item:<catalog id>`, see item-fx.js). Loaded lazily (ensurePlanDetails() in app.js), not at startup.
// verbatim: true = official text from the System Reference Document 5.2.1 (SRD 5.2.1), copied word for word; only line-break hyphenation was repaired and paragraph breaks restored. 'cat' is the item's type/rarity line from the SRD; 'source' is the SRD page. Tables are kept as simple lines with " | " between cells.
// For the "+1, +2, or +3" families (Armor, Shield, Weapon, Ammunition, Wand of the War Mage), the Giant Strength belt/potion and the Ioun Stones the SRD has one entry for the whole family: each plan or item shows that family text (for Ioun Stones, the intro plus the paragraph of that stone).
// verbatim: false = our own short summary (max about 200 characters), NOT copied from any book or wiki. source 'community, unverified' = item from Eberron / Tasha's that is not in the SRD; the summary follows the community notes in item-fx.js and may be wrong. source 'own words' = a plain explanation of how a generic plan works.
// Attribution (CC-BY-4.0): This work includes material from the System Reference Document 5.2.1 ("SRD 5.2.1") by Wizards of the Coast LLC, available at https://www.dndbeyond.com/srd. The SRD 5.2.1 is licensed under the Creative Commons Attribution 4.0 International License, available at https://creativecommons.org/licenses/by/4.0/legalcode.
const T = (cat, desc, page) => ({ cat, desc, verbatim: true, source: `SRD 5.2.1 p.${page}` });
const W = (cat, desc, source) => ({ cat, desc, verbatim: false, source });
const s1 = T("Wondrous Item, Uncommon", "This bag has an interior space considerably larger than its outside dimensions—roughly 2 feet square and 4 feet deep on the inside. The bag can hold up to 500 pounds, not exceeding a volume of 64 cubic feet. The bag weighs 5 pounds, regardless of its contents. Retrieving an item from the bag requires a Utilize action.\n\nIf the bag is overloaded, pierced, or torn, it is destroyed, and its contents are scattered in the Astral Plane. If the bag is turned inside out, its contents spill forth unharmed, but the bag must be put right before it can be used again. The bag holds enough air for 10 minutes of breathing, divided by the number of breathing creatures inside.\n\nPlacing a Bag of Holding inside an extradimensional space created by a Handy Haversack, Portable Hole, or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within a 10-foot-radius Sphere centered on the gate is sucked through it to a random location on the Astral Plane. The gate then closes. The gate is one-way and can’t be reopened.", 212);
const s2 = T("Wondrous Item, Uncommon", "While wearing these dark lenses, you have Darkvision out to 60 feet. If you already have Darkvision, wearing the goggles increases its range by 60 feet.", 224);
const s3 = T("Wondrous Item, Uncommon", "This 60-foot length of rope can hold up to 3,000 pounds. While holding one end of the rope, you can take a Magic action to command the other end of the rope to animate and move toward a destination you choose, up to the rope’s length away from you. That end moves 10 feet on your turn when you first command it and 10 feet at the start of each of your subsequent turns until reaching its destination or until you tell it to stop. You can also tell the rope to fasten itself securely to an object or to unfasten itself, to knot or unknot itself, or to coil itself for carrying.\n\nIf you tell the rope to knot, large knots appear at 1-foot intervals along the rope. While knotted, the rope shortens to a 50-foot length and grants Advantage on ability checks made to climb using the rope.\n\nThe rope has AC 20, HP 20, and Immunity to Poison and Psychic damage. It regains 1 Hit Point every 5 minutes as long as it has at least 1 Hit Point. If the rope drops to 0 Hit Points, it is destroyed.", 242);
const s4 = T("Wondrous Item, Uncommon", "Sending Stones come in pairs, with each stone carved to match the other so the pairing is easily recognized. While you touch one stone, you can cast Sending from it. The target is the bearer of the other stone. If no creature bears the other stone, you know that fact as soon as you use the stone, and you don’t cast the spell.\n\nOnce Sending is cast using either stone, the stones can’t be used again until the next dawn. If one of the stones in a pair is destroyed, the other one becomes nonmagical.", 243);
const s5 = T("Armor (Shield), Uncommon (+1), Rare (+2), or Very Rare (+3)", "While holding this Shield, you have a bonus to Armor Class determined by the Shield’s rarity, in addition to the Shield’s normal bonus to AC.", 243);
const s6 = T("Wand, Uncommon", "This wand has 3 charges. While holding it, you can expend 1 charge to cast Detect Magic from it. The wand regains 1d3 expended charges daily at dawn.", 251);
const s7 = T("Wand, Uncommon", "This wand has 3 charges and regains 1d3 expended charges daily at dawn. While holding it, you can take a Magic action to expend 1 charge, and if a secret door or trap is within 60 feet of you, the wand pulses and points at the one nearest to you.", 251);
const s8 = T("Wand, Uncommon (+1), Rare (+2), or Very Rare (+3) (Requires Attunement by a Spellcaster)", "While holding this wand, you gain a bonus to spell attack rolls determined by the wand’s rarity. In addition, you ignore Half Cover when making a spell attack roll.", 251);
const s9 = T("Weapon (Any Simple or Martial), Uncommon (+1), Rare (+2), or Very Rare (+3)", "You have a bonus to attack rolls and damage rolls made with this magic weapon. The bonus is determined by the weapon’s rarity.", 253);
const s10 = T("Armor (Any Light, Medium, or Heavy), Rare (+1), Very Rare (+2), or Legendary (+3)", "You have a bonus to Armor Class while wearing this armor. The bonus is determined by its rarity.", 210);
const s11 = T("Wondrous Item, Uncommon", "While you wear these boots, your steps make no sound, regardless of the surface you are moving across. You also have Advantage on Dexterity (Stealth) checks.", 213);
const s12 = T("Wondrous Item, Uncommon (Requires Attunement)", "While you wear this cloak, Wisdom (Perception) checks made to perceive you have Disadvantage, and you have Advantage on Dexterity (Stealth) checks.", 215);
const s13 = T("Wondrous Item, Uncommon (Requires Attunement)", "While wearing this cloak, you can breathe underwater, and you have a Swim Speed of 60 feet.", 216);
const s14 = T("Wondrous Item, Uncommon (Requires Attunement)", "These crystal lenses fit over the eyes. They have 3 charges. While wearing them, you can expend 1 or more charges to cast Charm Person (save DC 13). For 1 charge, you cast the level 1 version of the spell. You increase the spell’s level by one for each additional charge you expend. The lenses regain all expended charges daily at dawn.", 221);
const s15 = T("Wondrous Item, Uncommon", "These crystal lenses fit over the eyes. While wearing them, your vision improves significantly out to a range of 1 foot, granting you Darkvision within that range and Advantage on Intelligence (Investigation) checks made to examine something within that range.", 221);
const s16 = T("Wondrous Item, Uncommon", "These gloves are imperceptible while worn. While wearing them, you gain a +5 bonus to Dexterity (Sleight of Hand) checks.", 224);
const s17 = T("Wondrous Item, Uncommon", "While lit, this hooded lantern burns for 6 hours on 1 pint of oil, shedding Bright Light in a 30-foot radius and Dim Light for an additional 30 feet. Invisible creatures and objects are visible as long as they are in the lantern’s Bright Light. You can take a Utilize action to lower the hood, reducing the lantern’s light to Dim Light in a 5-foot radius.", 228);
const s18 = T("Wondrous Item, Uncommon (Requires Attunement)", "While wearing this necklace, you can breathe normally in any environment, and you have Advantage on saving throws made to avoid or end the Poisoned condition.", 232);
const s19 = T("Wondrous Item, Uncommon", "These pipes have 3 charges and regain 1d3 expended charges daily at dawn. You can take a Magic action to play them and expend 1 charge to create an eerie, spellbinding tune. Each creature of your choice within 30 feet of you must succeed on a DC 15 Wisdom saving throw or have the Frightened condition for 1 minute. A creature that fails the save repeats it at the end of each of its turns, ending the effect on itself on a success. A creature that succeeds on its save is immune to the effect of these pipes for 24 hours.", 234);
const s20 = T("Ring, Uncommon", "You have a Swim Speed of 40 feet while wearing this ring.", 239);
const s21 = T("Ring, Uncommon", "While wearing this ring, you cast Water Walk from it, targeting only yourself.", 239);
const s22 = T("Armor (Shield), Uncommon", "While holding this Shield, you have Advantage on Initiative rolls and Wisdom (Perception) checks. The Shield is emblazoned with a symbol of an eye.", 243);
const s23 = T("Wand, Uncommon", "This wand has 7 charges. While holding it, you can expend no more than 3 charges to cast Magic Missile from it. For 1 charge, you cast the level 1 version of the spell. You can increase the spell’s level by 1 for each additional charge you expend.\n\nRegaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.", 251);
const s24 = T("Wand, Uncommon (Requires Attunement by a Spellcaster)", "This wand has 7 charges. While holding it, you can expend 1 charge to cast Web (save DC 13) from it.\n\nRegaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.", 251);
const s25 = T("Weapon (Any Simple or Martial), Uncommon (Requires Attunement)", "As long as this weapon is within your reach and you are attuned to it, you and allies within 30 feet of you gain the following benefits.\n\nAlarm. The weapon magically awakens each subject who is sleeping naturally when combat begins. This benefit doesn’t wake a subject from magically induced sleep.\n\nSupernatural Readiness. Each subject has Advantage on its Initiative rolls.", 253);
const s26 = T("Armor (Any Light, Medium, or Heavy), Rare (Requires Attunement)", "You have Resistance to one type of damage while you wear this armor. The GM chooses the type or determines it randomly by rolling on the following table.\n\n1d10 | Damage Type | 1d10 | Damage Type\n1 | Acid | 6 | Necrotic\n2 | Cold | 7 | Poison\n3 | Fire | 8 | Psychic\n4 | Force | 9 | Radiant\n5 | Lightning | 10 | Thunder", 210);
const s27 = T("Weapon (Dagger), Rare", "You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.\n\nYou can take a Bonus Action to magically coat the blade with poison. The poison remains for 1 minute or until an attack using this weapon hits a creature. That creature must succeed on a DC 15 Constitution saving throw or take 2d10 Poison damage and have the Poisoned condition for 1 minute. The weapon can’t be used this way again until the next dawn.", 216);
const s28 = T("Armor (Chain Mail or Chain Shirt), Rare", "You gain a +1 bonus to Armor Class while you wear this armor. You are considered trained with this armor even if you lack training with Medium or Heavy armor.", 220);
const s29 = T("Ring, Rare (Requires Attunement)", "When you fall while wearing this ring, you descend 60 feet per round and take no damage from falling.", 238);
const s30 = T("Ring, Uncommon (Requires Attunement)", "While wearing this ring, you can cast Jump from it, but can target only yourself when you do so.", 238);
const s31 = T("Ring, Uncommon (Requires Attunement)", "While wearing this ring, you are immune to magic that allows other creatures to read your thoughts, determine whether you are lying, know your alignment, or know your creature type. Creatures can telepathically communicate with you only if you allow it.\n\nYou can take a Magic action to cause the ring to become imperceptible until you take another Magic action to make it perceptible, until you remove the ring, or until you die.\n\nIf you die while wearing the ring, your soul enters it, unless it already houses a soul. You can remain in the ring or depart for the afterlife. As long as your soul is in the ring, you can telepathically communicate with any creature wearing it. A wearer can’t prevent this telepathic communication.", 238);
const s32 = T("Armor (Shield), Rare (Requires Attunement)", "You gain a +2 bonus to Armor Class against ranged attack rolls while you wield this Shield. This bonus is in addition to the Shield’s normal bonus to AC.\n\nWhenever an attacker makes a ranged attack roll against a target within 5 feet of you, you can take a Reaction to become the target of the attack instead.", 211);
const s33 = T("Weapon (Any Melee Weapon), Rare (Requires Attunement)", "While holding this magic weapon, you can take a Bonus Action and use a command word to cause flames to engulf the damage-dealing part of the weapon. These flames shed Bright Light in a 40-foot radius and Dim Light for an additional 40 feet. While the weapon is ablaze, it deals an extra 2d6 Fire damage on a hit. The flames last until you take a Bonus Action to issue the command again or until you drop, stow, or sheathe the weapon.", 223);
const s34 = T("Ring, Rare (Requires Attunement)", "While you wear this ring, Difficult Terrain doesn’t cost you extra movement. In addition, magic can neither reduce any of your Speeds nor cause you to have the Paralyzed or Restrained condition.", 238);
const s35 = T("Ring, Rare (Requires Attunement)", "You gain a +1 bonus to Armor Class and saving throws while wearing this ring.", 238);
const s36 = T("Ring, Rare (Requires Attunement)", "This ring has 3 charges and regains 1d3 expended charges daily at dawn. While wearing the ring, you can take a Magic action to expend 1 to 3 charges to make a ranged spell attack against one creature you can see within 60 feet of yourself. The ring produces a spectral ram’s head and makes its attack roll with a +7 bonus. On a hit, for each charge you spend, the target takes 2d10 Force damage and is pushed 5 feet away from you.\n\nAlternatively, you can expend 1 to 3 of the ring’s charges as a Magic action to try to break a nonmagical object you can see within 60 feet of yourself that isn’t being worn or carried. The ring makes a Strength check with a +5 bonus for each charge you spend.", 239);
const s37 = T("Weapon (Any Ammunition), Uncommon (+1), Rare (+2), or Very Rare (+3)", "You have a bonus to attack rolls and damage rolls made with this piece of magic ammunition. The bonus is determined by the rarity of the ammunition. Once it hits a target, the ammunition is no longer magical.\n\nThis ammunition is typically found or sold in quantities of ten or twenty pieces. Ten pieces of this ammunition are equivalent in value to a potion of the same rarity.", 209);
const s38 = T("Wondrous Item, Uncommon (Requires Attunement)", "You gain a +1 bonus to Armor Class and saving throws while you wear this cloak.", 216);
const s39 = T("Wondrous Item, Very Rare (Requires Attunement)", "This black or dark-blue robe is embroidered with small white or silver stars. You gain a +1 bonus to saving throws while you wear it.\n\nSix stars, located on the robe’s upper-front portion, are particularly large. While wearing this robe, you can take a Magic action to remove one of the stars and expend it to cast the level 5 version of Magic Missile. Daily at dusk, 1d6 removed stars reappear on the robe.\n\nWhile you wear the robe, you can take a Magic action to enter the Astral Plane along with everything you are wearing and carrying. You remain there until you take a Magic action to return to the plane you were on. You reappear in the last space you occupied or, if that space is occupied, the nearest unoccupied space.", 240);
const s40 = T("Wondrous Item, Uncommon (Requires Attunement)", "While this polished agate is on your person, you gain a +1 bonus to ability checks and saving throws.", 248);
const s41 = T("Wondrous Item, Legendary (Requires Attunement)", "This beetle-shaped medallion provides three benefits while it is on your person.\n\nDefense. You gain a +1 bonus to Armor Class.\n\nPreservation. The scarab has 12 charges. If you fail a saving throw against a Necromancy spell or a harmful effect originating from an Undead, you can take a Reaction to expend 1 charge and turn the failed save into a successful one. The scarab crumbles into powder and is destroyed when its last charge is expended.\n\nSpell Resistance. You have Advantage on saving throws against spells.", 243);
const s42 = T("Wondrous Item, Rare (Requires Attunement)", "While wearing these bracers, you gain a +2 bonus to Armor Class if you are wearing no armor and using no Shield.", 214);
const s43 = T("Armor (Shield), Very Rare (Requires Attunement)", "While holding this Shield, you have a +2 bonus to Armor Class. This bonus is in addition to the Shield’s normal bonus to AC.\n\nThe Shield has the following additional properties that you can use while holding it.\n\nForceful Bash. When you take the Attack action, you can make one of the attack rolls using the Shield against a target within 5 feet of yourself. Apply your Proficiency Bonus and Strength modifier to the attack roll. On a hit, the Shield deals Force damage to the target equal to 2d6 + 2 plus your Strength modifier, and if the target is a creature, you can push it up to 10 feet directly away from yourself. If the creature is your size or smaller, you can also knock it down, giving it the Prone condition.\n\nProtective Field. As a Reaction, when you or an ally you can see within 5 feet of you is targeted by an attack or makes a saving throw against an area of effect, you can use the Shield to create an immobile 5-foot Emanation originating from you. When the Emanation appears, any creatures or objects not fully contained within it are pushed into the nearest unoccupied spaces outside it. The attack or area of effect that triggered the Reaction has no effect on creatures and objects inside the Emanation, which lasts as long as you maintain Concentration, up to 1 minute. Nothing can pass into or out of the Emanation. A creature or object inside the Emanation can’t be damaged by attacks or effects originating from outside, nor can a creature inside the Emanation damage anything outside it. Once this property is used, it can’t be used again until the next dawn.", 243);
const s44 = T("Armor (Half Plate Armor or Plate Armor), Very Rare", "While wearing this armor, you gain a +2 bonus to Armor Class. In addition, if an effect moves you against your will along the ground, you can take a Reaction to reduce the distance you are moved by up to 10 feet.", 219);
const s45 = T("Armor (Studded Leather Armor), Rare", "While wearing this armor, you gain a +1 bonus to Armor Class. You can also take a Bonus Action to cause the armor to assume the appearance of a normal set of clothing or some other kind of armor. You decide what it looks like—including color, style, and accessories—but the armor retains its normal bulk and weight. The illusory appearance lasts until you use this property again or doff the armor.", 223);
const s46 = T("Armor (Any Light, Medium, or Heavy), Very Rare (Requires Attunement)", "While wearing this armor, you gain a +1 bonus to Armor Class, and you know Abyssal. In addition, the armor’s clawed gauntlets allow your Unarmed Strikes to deal 1d8 Slashing damage instead of the usual Bludgeoning damage, and you gain a +1 bonus to the attack and damage rolls of your Unarmed Strikes.\n\nCurse. Once you don this cursed armor, you can’t doff it unless you are targeted by a Remove Curse spell or similar magic. While wearing the armor, you have Disadvantage on attack rolls against demons and on saving throws against their spells and special abilities.", 218);
const s47 = T("Armor (Scale Mail), Very Rare (Requires Attunement)", "Dragon Scale Mail is made of the scales of one kind of dragon. Sometimes dragons collect their cast-off scales and gift them. Other times, hunters carefully preserve the hide of a dead dragon. In either case, Dragon Scale Mail is highly valued.\n\nWhile wearing this armor, you gain a +1 bonus to Armor Class, you have Advantage on saving throws against the breath weapons of Dragons, and you have Resistance to one damage type determined by the kind of dragon that provided the scales (see the accompanying table).\n\nAdditionally, you can focus your senses as a Magic action to discern the distance and direction to the closest dragon within 30 miles of yourself that is of the same type as the armor. This action can’t be used again until the next dawn.\n\nDragon | Resistance | Dragon | Resistance\nBlack | Acid | Gold | Fire\nBlue | Lightning | Green | Poison\nBrass | Fire | Red | Fire\nBronze | Lightning | Silver | Cold\nCopper | Acid | White | Cold", 218);
const s48 = T("Armor (Plate Armor), Legendary (Requires Attunement)", "You have Resistance to Bludgeoning, Piercing, and Slashing damage while you wear this armor.\n\nMetal Shell. You can take a Magic action to give yourself Immunity to Bludgeoning, Piercing, and Slashing damage for 10 minutes or until you are no longer wearing the armor. Once this property is used, it can’t be used again until the next dawn.", 210);
const s49 = T("Armor (Any Light, Medium, or Heavy), Rare (Requires Attunement)", "While wearing this armor, you have Resistance to one of the following damage types: Bludgeoning, Piercing, or Slashing. The GM chooses the type or determines it randomly.\n\nCurse. This armor is cursed, a fact that is revealed only when the Identify spell is cast on the armor or you attune to it. Attuning to the armor curses you until you are targeted by a Remove Curse spell or similar magic; removing the armor fails to end the curse. While cursed, you have Vulnerability to two of the three damage types associated with the armor (not the one to which it grants Resistance).", 211);
const s50 = T("Armor (Any Medium or Heavy, Except Hide Armor), Uncommon", "This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you’re wearing it, any Critical Hit against you becomes a normal hit.", 209);
const s51 = T("Armor (Any Medium or Heavy, Except Hide Armor), Uncommon", "Mithral is a light, flexible metal. Armor made of this substance can be worn under normal clothes. If the armor normally imposes Disadvantage on Dexterity (Stealth) checks or has a Strength requirement, the mithral version of the armor doesn’t.", 231);
const s52 = T("Wondrous Item, Rare (Requires Attunement)", "Your Constitution is 19 while you wear this amulet. It has no effect on you if your Constitution is 19 or higher without it.", 209);
const s53 = T("Wondrous Item, Uncommon (Requires Attunement)", "Your Strength is 19 while you wear these gauntlets. They have no effect on you if your Strength is 19 or higher without them.", 223);
const s54 = T("Wondrous Item, Uncommon (Requires Attunement)", "Your Intelligence is 19 while you wear this headband. It has no effect on you if your Intelligence is 19 or higher without it.", 225);
const s55 = T("Wondrous Item, Rarity Varies (Requires Attunement)", "While wearing this belt, your Strength changes to a score granted by the belt. The type of giant determines the score (see the table below). The item has no effect on you if your Strength without the belt is equal to or greater than the belt’s score.\n\nBelt | Str. | Rarity\nBelt of Giant Strength (hill) | 21 | Rare\nBelt of Giant Strength (frost or stone) | 23 | Very Rare\nBelt of Giant Strength (fire) | 25 | Very Rare\nBelt of Giant Strength (cloud) | 27 | Legendary\nBelt of Giant Strength (storm) | 29 | Legendary", 213);
const s56 = T("Potion, Rarity Varies", "When you drink this potion, your Strength score changes for 1 hour. The type of giant determines the score (see the table below). The potion has no effect on you if your Strength is equal to or greater than that score.\n\nThis potion’s transparent liquid has floating in it a sliver of light resembling a giant’s fingernail.\n\nPotion | Str. | Rarity\nPotion of Giant Strength (hill) | 21 | Uncommon\nPotion of Giant Strength (frost or stone) | 23 | Rare\nPotion of Giant Strength (fire) | 25 | Rare\nPotion of Giant Strength (cloud) | 27 | Very Rare\nPotion of Giant Strength (storm) | 29 | Legendary", 235);
const s57 = T("Wondrous Item, Rare (Requires Attunement)", "While wearing this belt, you gain the following benefits:\n\nDwarvish. You know Dwarvish.\n\nFriend of Dwarvenkind. You have Advantage on Charisma (Persuasion) checks made to interact with dwarves and duergar.\n\nToughness. Your Constitution increases by 2, to a maximum of 20.\n\nIn addition, while attuned to the belt, you have a 50 percent chance each day at dawn of growing a full beard if you can grow one, or a thicker beard if you already have one.\n\nIf you aren’t a dwarf or duergar, you gain the following additional benefits while wearing the belt:\n\nDarkvision. You have Darkvision with a range of 60 feet.\n\nResilience. You have Resistance to Poison damage. You also have Advantage on saving throws you make to avoid or end the Poisoned condition.", 213);
const s58 = T("Wondrous Item, Rarity Varies (Requires Attunement)", "Roughly marble sized, Ioun Stones are named after Ioun, a god of knowledge and prophecy revered on some worlds. Many types of Ioun Stones exist, each type a distinct combination of shape and color.\n\nWhen you take a Magic action to toss an Ioun Stone into the air, the stone orbits your head at a distance of 1d3 feet, conferring its benefit to you while doing so. You can have up to three Ioun Stones orbiting your head at the same time.\n\nEach Ioun Stone orbiting your head is considered to be an object you are wearing. The orbiting stone avoids contact with other creatures and objects, adjusting its orbit to avoid collisions and thwarting all attempts by other creatures to attack or snatch it.\n\nAs a Utilize action, you can seize and stow any number of Ioun Stones orbiting your head. If your Attunement to an Ioun Stone ends while it’s orbiting your head, the stone falls as though you had dropped it.\n\nThe type of stone determines its rarity and effects.\n\nAgility (Very Rare). Your Dexterity increases by 2, to a maximum of 20, while this deep-red sphere orbits your head.", 227);
const s59 = T("Wondrous Item, Rarity Varies (Requires Attunement)", "Roughly marble sized, Ioun Stones are named after Ioun, a god of knowledge and prophecy revered on some worlds. Many types of Ioun Stones exist, each type a distinct combination of shape and color.\n\nWhen you take a Magic action to toss an Ioun Stone into the air, the stone orbits your head at a distance of 1d3 feet, conferring its benefit to you while doing so. You can have up to three Ioun Stones orbiting your head at the same time.\n\nEach Ioun Stone orbiting your head is considered to be an object you are wearing. The orbiting stone avoids contact with other creatures and objects, adjusting its orbit to avoid collisions and thwarting all attempts by other creatures to attack or snatch it.\n\nAs a Utilize action, you can seize and stow any number of Ioun Stones orbiting your head. If your Attunement to an Ioun Stone ends while it’s orbiting your head, the stone falls as though you had dropped it.\n\nThe type of stone determines its rarity and effects.\n\nFortitude (Very Rare). Your Constitution increases by 2, to a maximum of 20, while this pink rhomboid orbits your head.", 227);
const s60 = T("Wondrous Item, Rarity Varies (Requires Attunement)", "Roughly marble sized, Ioun Stones are named after Ioun, a god of knowledge and prophecy revered on some worlds. Many types of Ioun Stones exist, each type a distinct combination of shape and color.\n\nWhen you take a Magic action to toss an Ioun Stone into the air, the stone orbits your head at a distance of 1d3 feet, conferring its benefit to you while doing so. You can have up to three Ioun Stones orbiting your head at the same time.\n\nEach Ioun Stone orbiting your head is considered to be an object you are wearing. The orbiting stone avoids contact with other creatures and objects, adjusting its orbit to avoid collisions and thwarting all attempts by other creatures to attack or snatch it.\n\nAs a Utilize action, you can seize and stow any number of Ioun Stones orbiting your head. If your Attunement to an Ioun Stone ends while it’s orbiting your head, the stone falls as though you had dropped it.\n\nThe type of stone determines its rarity and effects.\n\nInsight (Very Rare). Your Wisdom increases by 2, to a maximum of 20, while this incandescent blue sphere orbits your head.", 227);
const s61 = T("Wondrous Item, Rarity Varies (Requires Attunement)", "Roughly marble sized, Ioun Stones are named after Ioun, a god of knowledge and prophecy revered on some worlds. Many types of Ioun Stones exist, each type a distinct combination of shape and color.\n\nWhen you take a Magic action to toss an Ioun Stone into the air, the stone orbits your head at a distance of 1d3 feet, conferring its benefit to you while doing so. You can have up to three Ioun Stones orbiting your head at the same time.\n\nEach Ioun Stone orbiting your head is considered to be an object you are wearing. The orbiting stone avoids contact with other creatures and objects, adjusting its orbit to avoid collisions and thwarting all attempts by other creatures to attack or snatch it.\n\nAs a Utilize action, you can seize and stow any number of Ioun Stones orbiting your head. If your Attunement to an Ioun Stone ends while it’s orbiting your head, the stone falls as though you had dropped it.\n\nThe type of stone determines its rarity and effects.\n\nIntellect (Very Rare). Your Intelligence increases by 2, to a maximum of 20, while this marbled scarlet and blue sphere orbits your head.", 227);
const s62 = T("Wondrous Item, Rarity Varies (Requires Attunement)", "Roughly marble sized, Ioun Stones are named after Ioun, a god of knowledge and prophecy revered on some worlds. Many types of Ioun Stones exist, each type a distinct combination of shape and color.\n\nWhen you take a Magic action to toss an Ioun Stone into the air, the stone orbits your head at a distance of 1d3 feet, conferring its benefit to you while doing so. You can have up to three Ioun Stones orbiting your head at the same time.\n\nEach Ioun Stone orbiting your head is considered to be an object you are wearing. The orbiting stone avoids contact with other creatures and objects, adjusting its orbit to avoid collisions and thwarting all attempts by other creatures to attack or snatch it.\n\nAs a Utilize action, you can seize and stow any number of Ioun Stones orbiting your head. If your Attunement to an Ioun Stone ends while it’s orbiting your head, the stone falls as though you had dropped it.\n\nThe type of stone determines its rarity and effects.\n\nLeadership (Very Rare). Your Charisma increases by 2, to a maximum of 20, while this marbled pink and green sphere orbits your head.", 227);
